/**
 * Row and result shapes for the DiaLearn database.
 *
 * Extracted from the schema rather than written by hand, so they match what
 * PostgreSQL actually returns. They previously came from a file generated by
 * `supabase gen types`; that generator is gone, so these are maintained here.
 *
 * Keep them in step with supabase/migrations — the API validates its own
 * responses, so a drift surfaces as a type error here rather than bad data.
 *
 * Enums live in ./domain-types.
 */
import type {
  AppRole,
  AssignmentStatus,
  BookingStatus,
  CommissionModel,
  NotificationChannel,
  PaymentStatus,
  PayoutStatus,
  ResourceType,
  VerificationStatus,
} from "./domain-types";

export type Json = string | number | boolean | null | { [key: string]: Json | undefined } | Json[];

